$ErrorActionPreference='Stop';$thumb='220DD82C37FCF36048D59E4F10113185D81D5DC7';$subject='CN=SafeUpload Test Signing'
$product=Get-CimInstance Win32_ComputerSystemProduct;$stores=@()
foreach($path in @('Cert:\LocalMachine\Root','Cert:\LocalMachine\TrustedPublisher','Cert:\CurrentUser\My')){$matches=@(Get-ChildItem -LiteralPath $path -ErrorAction SilentlyContinue|Where-Object {$_.Thumbprint -ceq $thumb -or $_.Subject -ceq $subject}|ForEach-Object {[ordered]@{Thumbprint=$_.Thumbprint;Subject=$_.Subject;HasPrivateKey=[bool]$_.HasPrivateKey;NotAfterUtc=$_.NotAfter.ToUniversalTime().ToString('o')}});$stores+=[ordered]@{Store=$path;Matches=$matches}}
[ordered]@{Status='Completed';UTC=[DateTime]::UtcNow.ToString('o');ComputerName=$env:COMPUTERNAME;UUID=$product.UUID;User=[Security.Principal.WindowsIdentity]::GetCurrent().Name;TestSigningBcdedit=(bcdedit.exe /enum '{current}' | Select-String -Pattern 'testsigning');SafeUploadCertificateStores=$stores;ReadOnly=$true}|ConvertTo-Json -Depth 8 -Compress
